def test_news_scores_and_recommendations_are_code_calculated():
    toolbox = Toolbox()
    labels = {
        "N1": "bullish", "N2": "neutral", "N3": "bullish",
        "N4": "bullish", "N5": "bearish", "N6": "neutral",
        "N7": "bearish", "N8": "bearish", "N9": "bearish",
    }
    expected = {"GC=F": (2, "LONG"), "BZ=F": (0, "NO_TRADE"), "NG=F": (-3, "SHORT")}
    for ticker, (news_score, recommendation) in expected.items():
        articles = toolbox.get_news(ticker)["articles"]
        scored = toolbox.score_news(
            ticker,
            [{"id": article["id"], "sentiment": labels.get(article["id"], "neutral")} for article in articles],
        )
        prices = toolbox.get_prices(ticker)
        assert scored["news_score"] == news_score
        assert policy_recommendation(prices["trend"], news_score) == recommendation

