# pytest fixtures: decision, trade, reasons, input_tokens, output_tokens
def verdict_reply(
    decision="APPROVED",
    trade=None,
    reasons=None,
    input_tokens: int = 10,
    output_tokens: int = 5,
):
    trade = trade or {
        "instrument": "Brent crude oil",
        "direction": "BUY",
        "size": 100,
        "entry": 88.5,
        "stop_loss": 88.0,
    }
    return SimpleNamespace(
        content=[
            SimpleNamespace(
                type="tool_use",
                name="submit_verdict",
                input={"decision": decision, "trade": trade, "reasons": reasons or ["Within limits"]},
            )
        ],
        stop_reason="tool_use",
        usage=SimpleNamespace(input_tokens=input_tokens, output_tokens=output_tokens),
    )

def test_cli_adapter_formats_history_and_returns_text():
    client = ClaudeCodeClient()
    completed = type("Result", (), {"stdout": json.dumps({"result": "Ready", "usage": {}})})()
    request = {
        "system": "Be concise.",
        "messages": [
            {"role": "user", "content": "Start"},
            {
                "role": "assistant",
                "content": [SimpleNamespace(type="text", text="Earlier reply")],
            },
        ],
    }
with patch("desk.claude_code_client.subprocess.run", return_value=completed) as run:
        response = client.messages.create(**request)
assert response.content[0].text == "Ready"
    assert "USER:\nStart" in run.call_args.kwargs["input"]
    assert "ASSISTANT:\nEarlier reply" in run.call_args.kwargs["input"]

